def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_m, last_o = history[-1]

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
    opp_def = n - opp_c

    if n < 6:
        return 'D' if last_o == 'D' else 'C'

    start5 = max(0, n - 5)
    r5 = 0
    for i in range(start5, n):
        if history[i][1] == 'D':
            r5 += 1

    start10 = max(0, n - 10)
    r10 = 0
    for i in range(start10, n):
        if history[i][1] == 'D':
            r10 += 1

    streak_D = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_D += 1
        else:
            break

    streak_C = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            streak_C += 1
        else:
            break

    punish = 0
    forgive = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'D':
                punish += 1
            else:
                forgive += 1

    if opp_def > max(1, int(0.32 * n)) or r10 >= 8:
        if last_o == 'C' and r5 == 0 and rng.random() < 0.12:
            return 'C'
        return 'D'

    if last_o == 'D':
        if streak_D >= 3:
            if rng.random() < 0.30:
                return 'C'
            return 'D'

        if r5 >= 2:
            if rng.random() < 0.15:
                return 'C'
            return 'D'

        if last_m == 'C' and punish > 0 and r5 <= 1 and opp_c >= n - 3:
            if rng.random() < 0.70:
                return 'C'
            return 'D'

        if last_m == 'D' and punish > 0 and opp_c >= n - 2:
            if rng.random() < 0.75:
                return 'C'
            return 'D'

        if last_m == 'C' and opp_c >= n - 1 and punish == 0 and forgive >= 1:
            if rng.random() < 0.30:
                return 'C'
            return 'D'

        return 'D'

    if last_m == 'D':
        if punish == 0 and forgive >= 3:
            if rng.random() < 0.80:
                return 'D'

        if punish == 0 and forgive == 2:
            if rng.random() < 0.55:
                return 'D'

        if punish == 0 and forgive == 1 and n >= 85:
            if rng.random() < 0.35:
                return 'D'

        if rng.random() < 0.90:
            return 'C'
        return 'D'

    if punish == 0:
        if forgive >= 3 and opp_def == 0:
            if rng.random() < 0.85:
                return 'D'

        if forgive >= 2 and opp_def <= max(1, int(0.02 * n) + 1):
            if n >= 85 and rng.random() < 0.60:
                return 'D'
            if rng.random() < 0.25:
                return 'D'

        if forgive == 1 and opp_def == 0:
            if n >= 90 and rng.random() < 0.35:
                return 'D'
            if rng.random() < 0.12:
                return 'D'

        if forgive == 1 and opp_def <= 2:
            if n >= 95 and rng.random() < 0.25:
                return 'D'

        if opp_def == 0 and streak_C >= 8:
            if n >= 95 and rng.random() < 0.15:
                return 'D'
            if n >= 88 and rng.random() < 0.04:
                return 'D'

        if opp_c >= n - 1 and r5 == 0 and n >= 96 and rng.random() < 0.10:
            return 'D'

    return 'C'
